svg.script:
//
    (function() {
      // State Variables
      var currentMode = 'normal'; // 'normal', '2mn', '1mn'
      var selectedStructure = 'none';
      var isAnimating = false;

      // DOM Elements
      var svgRoot = document.getElementById('fm1p5-svg-main');
      var btnTheme = document.getElementById('fm1p5-btn-theme');
      var btnStrike = document.getElementById('fm1p5-btn-strike');

      var btnScenNormal = document.getElementById('fm1p5-btn-scen-normal');
      var btnScen2mn = document.getElementById('fm1p5-btn-scen-2mn');
      var btnScen1mn = document.getElementById('fm1p5-btn-scen-1mn');

      var bgNormal = document.getElementById('fm1p5-bg-scen-normal');
      var bg2mn = document.getElementById('fm1p5-bg-scen-2mn');
      var bg1mn = document.getElementById('fm1p5-bg-scen-1mn');

      var hammerAnim = document.getElementById('fm1p5-hammer-anim');
      var lowerLeg = document.getElementById('fm1p5-lower-leg');
      var impactBurst = document.getElementById('fm1p5-impact-burst');

      var pulseAff = document.getElementById('fm1p5-pulse-aff');
      var pulseEff = document.getElementById('fm1p5-pulse-eff');

      var pathAff = document.getElementById('fm1p5-path-aff');
      var pathEff = document.getElementById('fm1p5-path-eff');

      var lesionOverlay = document.getElementById('fm1p5-lesion-overlay');
      var lesionLine1 = document.getElementById('fm1p5-lesion-line-1');
      var lesionLine2 = document.getElementById('fm1p5-lesion-line-2');
      var lesionText = document.getElementById('fm1p5-lesion-text');

      var badgeBg = document.getElementById('fm1p5-status-badge-bg');
      var badgeTxt = document.getElementById('fm1p5-status-badge-txt');
      var meterBar = document.getElementById('fm1p5-meter-bar');

      var desc1 = document.getElementById('fm1p5-scen-desc-1');
      var desc2 = document.getElementById('fm1p5-scen-desc-2');
      var desc3 = document.getElementById('fm1p5-scen-desc-3');
      var desc4 = document.getElementById('fm1p5-scen-desc-4');

      var inspectorTitle = document.getElementById('fm1p5-inspector-title');
      var inspectorLine1 = document.getElementById('fm1p5-inspector-line-1');
      var inspectorLine2 = document.getElementById('fm1p5-inspector-line-2');
      var inspectorLine3 = document.getElementById('fm1p5-inspector-line-3');
      var inspectorLine4 = document.getElementById('fm1p5-inspector-line-4');
      var inspectorLine5 = document.getElementById('fm1p5-inspector-line-5');

      // Theme Handler
      btnTheme.addEventListener('click', function() {
        var currentTheme = svgRoot.getAttribute('data-theme');
        if (currentTheme === 'light') {
          svgRoot.removeAttribute('data-theme');
        } else {
          svgRoot.setAttribute('data-theme', 'light');
        }
      });

      // Scenario Switchers
      function setScenario(mode) {
        currentMode = mode;

        // Reset Button Styles
        bgNormal.setAttribute('fill', 'var(--fm1p5-card-start, #1e293b)');
        bgNormal.setAttribute('stroke', 'var(--fm1p5-green, #22c55e)');
        bgNormal.setAttribute('stroke-width', '1.5');

        bg2mn.setAttribute('fill', 'var(--fm1p5-card-start, #1e293b)');
        bg2mn.setAttribute('stroke', 'var(--fm1p5-red, #ef4444)');
        bg2mn.setAttribute('stroke-width', '1.5');

        bg1mn.setAttribute('fill', 'var(--fm1p5-card-start, #1e293b)');
        bg1mn.setAttribute('stroke', 'var(--fm1p5-amber, #f59e0b)');
        bg1mn.setAttribute('stroke-width', '1.5');

        lesionOverlay.setAttribute('opacity', '0');

        if (mode === 'normal') {
          bgNormal.setAttribute('fill', 'var(--fm1p5-green, #22c55e)');
          badgeBg.setAttribute('fill', 'var(--fm1p5-green, #22c55e)');
          badgeTxt.textContent = 'NORMO-REFLEXIA (2+)';
          meterBar.setAttribute('width', '70');
          meterBar.setAttribute('fill', 'var(--fm1p5-green, #22c55e)');

          desc1.textContent = 'Arco Monossináptico Íntegro (L2-L4)';
          desc2.textContent = '• Estiramento do fuso -> Aferência sensitiva Ia';
          desc3.textContent = '• Sinapse direta com 2º MN -> Contração de resposta';
          desc4.textContent = '• Modulação cortical preservada (Chute fisiológico)';
          desc4.setAttribute('fill', 'var(--fm1p5-cyan-light, #38bdf8)');

        } else if (mode === '2mn') {
          bg2mn.setAttribute('fill', 'var(--fm1p5-red, #ef4444)');
          badgeBg.setAttribute('fill', 'var(--fm1p5-red, #ef4444)');
          badgeTxt.textContent = 'ARREFLEXIA / 2º MN (0)';
          meterBar.setAttribute('width', '0');

          desc1.textContent = 'Lesão de 2º MN ou Nervo Periférico';
          desc2.textContent = '• Interrupção no arco local (raiz, gânglio ou motoneurônio)';
          desc3.textContent = '• O martelo estira, mas o sinal NÃO chega/retorna!';
          desc4.textContent = '• REGRA: "Só tem reflexo quem tem nervo!" (Abolido)';
          desc4.setAttribute('fill', 'var(--fm1p5-red, #ef4444)');

          // Draw Lesion Mark on Peripheral Nerve
          lesionOverlay.setAttribute('opacity', '1');
          lesionLine1.setAttribute('x1', '250'); lesionLine1.setAttribute('y1', '215');
          lesionLine1.setAttribute('x2', '270'); lesionLine1.setAttribute('y2', '235');
          lesionLine2.setAttribute('x1', '270'); lesionLine2.setAttribute('y1', '215');
          lesionLine2.setAttribute('x2', '250'); lesionLine2.setAttribute('y2', '235');
          lesionText.setAttribute('x', '260'); lesionText.setAttribute('y', '250');
          lesionText.textContent = '⚡ LESÃO DE NERVO/RAIZ';

        } else if (mode === '1mn') {
          bg1mn.setAttribute('fill', 'var(--fm1p5-amber, #f59e0b)');
          badgeBg.setAttribute('fill', 'var(--fm1p5-amber, #f59e0b)');
          badgeTxt.textContent = 'HIPERREFLEXIA / 1º MN (3+/4+)';
          meterBar.setAttribute('width', '140');
          meterBar.setAttribute('fill', 'var(--fm1p5-amber, #f59e0b)');

          desc1.textContent = 'Lesão de 1º MN / Trato Córtico-Espinal';
          desc2.textContent = '• Perda da inibição descendente central';
          desc3.textContent = '• O arco medular fica "solto" e hiper-exaltado';
          desc4.textContent = '• Pode gerar Clonus e expansão de área reflexógena!';
          desc4.setAttribute('fill', 'var(--fm1p5-amber, #f59e0b)');

          // Draw Lesion Mark on Corticospinal Tract
          lesionOverlay.setAttribute('opacity', '1');
          lesionLine1.setAttribute('x1', '195'); lesionLine1.setAttribute('y1', '145');
          lesionLine1.setAttribute('x2', '215'); lesionLine1.setAttribute('y2', '165');
          lesionLine2.setAttribute('x1', '215'); lesionLine2.setAttribute('y1', '145');
          lesionLine2.setAttribute('x2', '195'); lesionLine2.setAttribute('y2', '165');
          lesionText.setAttribute('x', '205'); lesionText.setAttribute('y', '180');
          lesionText.textContent = '⚡ LESÃO VIA PIRAMIDAL';
        }
      }

      btnScenNormal.addEventListener('click', function() { setScenario('normal'); });
      btnScen2mn.addEventListener('click', function() { setScenario('2mn'); });
      btnScen1mn.addEventListener('click', function() { setScenario('1mn'); });

      // Structure Inspector Content Map
      var inspectorMap = {
        'cortex': {
          title: 'Córtex Cerebral (Via Ascendente)',
          line1: '• Recebe colaterais que sobem pela coluna posterior.',
          line2: '• Função: Proporcionar a consciência de que o joelho foi batido.',
          line3: '• CRÍTICO: NÃO comanda nem inicia a resposta motora do chute!',
          line4: '• 1º Motoneurônio envia eferência inibitória descendente.',
          line5: ''
        },
        'medula': {
          title: 'Medula Espinhal (Nível L2–L4)',
          line1: '• Centro de integração do reflexo osteotendíneo patelar.',
          line2: '• Sinapse MONOSSINÁPTICA entre o neurônio Ia e o Motoneurônio Alfa.',
          line3: '• Interneurônio inibitório sincroniza o relaxamento do Isquiotibial.',
          line4: '• O arco fecha totalmente aqui, independente do cérebro!',
          line5: ''
        },
        'drg': {
          title: 'Gânglio da Raiz Dorsal (GRD)',
          line1: '• Contém o corpo celular do neurônio sensitivo pseudounipolar (Ia).',
          line2: '• Conduz o estímulo de estiramento do fuso muscular à medula.',
          line3: '• Lesões ganglionares/radiculares (2º MN) abolem o reflexo.',
          line4: '',
          line5: ''
        },
        'fuso': {
          title: 'Fuso Neuromuscular (Receptor)',
          line1: '• Mecanorreceptor intrafusal que detecta o estiramento rápido.',
          line2: '• A batida do martelo no tendão patelar estira o quadríceps.',
          line3: '• O fuso dispara potenciais de ação imediatos na fibra Ia.',
          line4: '',
          line5: ''
        },
        'tendon': {
          title: 'Tendão Patelar & Martelo',
          line1: '• O impacto súbito do martelo de reflexo deformará o tendão.',
          line2: '• Gera o estiramento mecânico passivo do músculo Quadríceps.',
          line3: '• Teste clássico de integridade do arco L2-L4 em provas.',
          line4: '',
          line5: ''
        },
        'quad': {
          title: 'Músculo Quadríceps (Efetor)',
          line1: '• Músculo efetor da extensão do joelho.',
          line2: '• Recebe o disparo motor do Neurônio Motor Alfa (2º MN).',
          line3: '• A contração rápida produz o "tranco/chute" involuntário.',
          line4: '',
          line5: ''
        }
      };

      function updateInspector(key) {
        selectedStructure = key;
        var info = inspectorMap[key];
        if (!info) return;

        inspectorTitle.textContent = info.title;
        inspectorLine1.textContent = info.line1;
        inspectorLine2.textContent = info.line2;
        inspectorLine3.textContent = info.line3;
        inspectorLine4.textContent = info.line4;
        inspectorLine5.textContent = info.line5;
      }

      // Attach Inspector Hotspot Click Handlers
      var hsCortex = document.getElementById('fm1p5-hs-cortex');
      var hsMedula = document.getElementById('fm1p5-hs-medula');
      var hsDrg = document.getElementById('fm1p5-hs-drg');
      var hsFuso = document.getElementById('fm1p5-hs-fuso');
      var hsTendon = document.getElementById('fm1p5-hs-tendon');
      var hsQuad = document.getElementById('fm1p5-hs-quad');

      if (hsCortex) hsCortex.addEventListener('click', function() { updateInspector('cortex'); });
      if (hsMedula) hsMedula.addEventListener('click', function() { updateInspector('medula'); });
      if (hsDrg) hsDrg.addEventListener('click', function() { updateInspector('drg'); });
      if (hsFuso) hsFuso.addEventListener('click', function() { updateInspector('fuso'); });
      if (hsTendon) hsTendon.addEventListener('click', function() { updateInspector('tendon'); });
      if (hsQuad) hsQuad.addEventListener('click', function() { updateInspector('quad'); });

      // ANIMATION ENGINE (HAMMER STRIKE & LEG KICK)
      function runHammerStrike() {
        if (isAnimating) return;
        isAnimating = true;

        // 1. Hammer Swing Animation
        var hammerAngle = 0;
        var swingForward = true;

        var swingInterval = setInterval(function() {
          if (swingForward) {
            hammerAngle += 6;
            if (hammerAngle >= 35) {
              swingForward = false;
              // Impact Moment!
              triggerImpactEffects();
            }
          } else {
            hammerAngle -= 4;
            if (hammerAngle <= 0) {
              hammerAngle = 0;
              clearInterval(swingInterval);
            }
          }
          hammerAnim.setAttribute('transform', 'rotate(' + hammerAngle + ' 0 0)');
        }, 16);
      }

      function triggerImpactEffects() {
        // Visual Burst on Tendon
        impactBurst.setAttribute('r', '5');
        impactBurst.setAttribute('opacity', '1');

        var burstOpacity = 1;
        var burstRadius = 5;
        var burstInterval = setInterval(function() {
          burstRadius += 3;
          burstOpacity -= 0.1;
          impactBurst.setAttribute('r', burstRadius);
          impactBurst.setAttribute('opacity', Math.max(0, burstOpacity));
          if (burstOpacity <= 0) clearInterval(burstInterval);
        }, 30);

        // Sensory Impulse Pulse Along Afferent Path
        animatePulse(pulseAff, pathAff, 300, function() {
          if (currentMode === '2mn') {
            // Blocked at nerve! No kick!
            isAnimating = false;
            return;
          }

          // Spinal Synapse firing, then Efferent Pulse down Motor Path
          animatePulse(pulseEff, pathEff, 250, function() {
            // Leg Kick Reaction!
            triggerLegKick();
          });
        });
      }

      function animatePulse(pulseElem, pathElem, duration, callback) {
        var pathLen = pathElem.getTotalLength();
        var startTime = null;

        pulseElem.setAttribute('opacity', '1');

        function step(timestamp) {
          if (!startTime) startTime = timestamp;
          var progress = (timestamp - startTime) / duration;
          if (progress > 1) progress = 1;

          var pt = pathElem.getPointAtLength(progress * pathLen);
          pulseElem.setAttribute('cx', pt.x);
          pulseElem.setAttribute('cy', pt.y);

          if (progress < 1) {
            requestAnimationFrame(step);
          } else {
            pulseElem.setAttribute('opacity', '0');
            if (callback) callback();
          }
        }
        requestAnimationFrame(step);
      }

      function triggerLegKick() {
        var maxKickAngle = 20; // Normal
        if (currentMode === '1mn') maxKickAngle = 45; // Exalted / Hyperreflexia
        if (currentMode === '2mn') maxKickAngle = 0;

        var legAngle = 0;
        var legRising = true;
        var kickCount = (currentMode === '1mn') ? 3 : 1; // Clonus bounce for 1st MN!
        var currentKick = 0;

        var kickInterval = setInterval(function() {
          if (legRising) {
            legAngle -= 5;
            if (legAngle <= -maxKickAngle) {
              legRising = false;
            }
          } else {
            legAngle += 3;
            if (legAngle >= 0) {
              legAngle = 0;
              currentKick++;
              if (currentKick >= kickCount) {
                clearInterval(kickInterval);
                isAnimating = false;
              } else {
                legRising = true;
                maxKickAngle *= 0.6; // Dampened clonus bounce
              }
            }
          }
          lowerLeg.setAttribute('transform', 'rotate(' + legAngle + ' 170 180)');
        }, 16);
      }

      btnStrike.addEventListener('click', runHammerStrike);
      var hammerGroup = document.getElementById('fm1p5-hammer-group');
      if (hammerGroup) hammerGroup.addEventListener('click', runHammerStrike);

      // Default scenario initialization
      setScenario('normal');

    })();
  //
